var a=[{title:`Porque acontece`,text:`As DOMS costumam seguir-se a movimentos pouco habituais e a contrações excêntricas repetidas, em que um músculo produz força enquanto se alonga. Estão envolvidos vários processos no músculo e nos tecidos à volta. O ácido láctico que sobra não é a causa. A intensidade das dores não mede a qualidade do treino.`},{title:`Como surgem e passam`,text:`As dores musculares podem começar várias horas depois de uma sessão, aumentar nos um a três dias seguintes e depois desaparecer. Um exercício familiar costuma causar menos dores com a mesma dose, o que se chama efeito de repetição do esforço. Não precisa de dores intensas ou duradouras para desenvolver força.`},{title:`Treinar com dores`,text:`As dores musculares ligeiras e dispersas costumam permitir caminhar, fazer mobilidade ou treinar de forma mais fácil, desde que se mova bem. Se as dores limitarem o movimento normal ou alterarem a sua técnica de levantamento, reduza a intensidade ou faça mais recuperação. Repetir logo uma sessão pouco habitual de grande volume raramente é uma boa forma de progredir. Progrida gradualmente nos exercícios familiares e não conte com o alongamento ou o retorno à calma para prevenir as dores do dia seguinte.`},{title:`Quando pedir ajuda`,text:`Dor aguda num ponto, muito inchaço, fraqueza evidente, urina escura, febre ou sintomas que pioram em vez de aliviar não são DOMS normais. Sinais graves, sobretudo urina escura com dor ou fraqueza muscular, precisam de avaliação médica rápida.`},{title:`Usar o TrainUp`,text:`Depois de um treino pode indicar dor ou desconforto, com a zona do corpo e o exercício. Qualquer dor recente significa que o plano não fica mais difícil quando o gera de novo. Se um exercício doer durante um treino, toque em «Sinto dor» para o terminar de imediato; fica fora dos seus planos até o retomar no Perfil.`}];var r=[{label:`NHS: dores musculares de início tardio`,url:`https://www.leicspart.nhs.uk/msk-physiotherapy-resources-getting-started/msk-physiotherapy-resources-faqs/`},{label:`Revisão da investigação: dores musculares de início tardio`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC13627368/`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:a,sources:r};export{s as default,a as sections,r as sources};